import raw from '../assets/nervous.json'
import { nervousNames } from './nervous-names'
import { buildSystem, type SystemEntry } from './system-model'

/**
 * The nervous system and the sense organs exported from Z-Anatomy, named from TA2
 * (assets/nervous.json, generated by tools/anatomy/gen-nervous.mjs). Each entry is a node of
 * nervous.glb. Its kind is its colour (a lobe, a nucleus, a nerve…); its section, the layer it
 * belongs to.
 */
export type NervousKind =
  | 'frontal'
  | 'parietal'
  | 'temporal'
  | 'occipital'
  | 'limbic'
  | 'insula'
  | 'sulcus'
  | 'nucleus'
  | 'white'
  | 'tract'
  | 'csf'
  | 'cerebellum'
  | 'brainstem'
  | 'cord-white'
  | 'cord-grey'
  | 'nerve'
  | 'meninges'
  | 'sense'

export type NervousSection = 'cerebrum' | 'deep' | 'cerebellum' | 'brainstem' | 'cord' | 'nerves' | 'meninges' | 'sense'

const CORTEX = new Set(['frontal', 'parietal', 'temporal', 'occipital', 'limbic', 'insula', 'sulcus'])

export const nervousSectionOf = (e: SystemEntry): NervousSection => {
  const groups = new Set(e.groups.map((g) => g.en))
  if (e.kind === 'nerve') return 'nerves'
  if (e.kind === 'meninges') return 'meninges'
  if (e.kind === 'sense') return 'sense'
  if (e.kind.startsWith('cord')) return 'cord'
  // The cranial nerve nuclei, the colliculi or the olive belong to the brainstem, whatever their colour.
  if (groups.has('Brainstem') || e.kind === 'brainstem') return 'brainstem'
  if (e.kind === 'cerebellum') return 'cerebellum'
  if (CORTEX.has(e.kind)) return 'cerebrum'
  return 'deep'
}

export const nervousSectionLabel: Record<NervousSection, string> = {
  cerebrum: 'Corteza cerebral',
  deep: 'Interior del cerebro',
  cerebellum: 'Cerebelo',
  brainstem: 'Tronco del encéfalo',
  cord: 'Médula espinal',
  nerves: 'Nervios',
  meninges: 'Meninges',
  sense: 'Órganos de los sentidos',
}

export const nervous = buildSystem(raw as SystemEntry[], nervousNames, nervousSectionOf)
